    t.id === 'sheepdog/fleet-seeds' ? { ...t, codeWorkTriage: undefined } : t);
  const sim = makeSim({ tasks });
  sim.at('2026-08-12T00:00Z', ({ world }) => { world.patScopeMissing = true; });
  sim.run('2026-08-12T00:00Z', '2026-08-14T12:00Z');

